(function registerDseListening2021Transcript(){"use strict";window.EDMUND_DSE_LISTENING_2021_TRANSCRIPT=Object.freeze({"partA":{"1":[{"start":2.63,"end":9.05,"speaker":"Exam Narrator","text":"Task 1. Bonnie, Cherie and Julian are discussing a work schedule to carry out the research"},{"start":9.05,"end":15.58,"speaker":"Exam Narrator","text":"on World Expos. Listen to the conversation and complete the note sheet below."},{"start":16.75,"end":24.59,"speaker":"Exam Narrator","text":"The first one has been provided as an example. You now have 30 seconds to study the task."},{"start":25.67,"end":31.03,"speaker":"Exam Narrator","text":"At the end of the task you will have 30 seconds to tidy up your answers."},{"start":62.94,"end":68.5,"speaker":"Bonnie","text":"Okay, I know you've started doing some work for this World Expos presentation we have to do."},{"start":68.88,"end":73.46,"speaker":"Bonnie","text":"So I just wanted to check where we are and maybe plan out the next few weeks."},{"start":74.28,"end":81.34,"speaker":"Bonnie","text":"Yeah, I was thinking the same. Jasmine has- Hold on, hold on. What was it about again?"},{"start":82.08,"end":88.52,"speaker":"Cherie","text":"Right. Well, the title we were given was An Overview of World Expos. Remember Julian?"},{"start":89.08,"end":93.77,"speaker":"Julian","text":"Oh yeah, vaguely. So when is it? The presentation."},{"start":94.75,"end":100.43,"speaker":"Cherie","text":"Well, that's what I was going to say. Jasmine's now confirmed all the details."},{"start":100.97,"end":105.55,"speaker":"Cherie","text":"So we're presenting on August 30th at half past nine."},{"start":106.51,"end":116.79,"speaker":"Julian","text":"Okay, right. August 30th at half past nine. That's early then. Wait, is that all three of us presenting?"},{"start":117.57,"end":119.51,"speaker":"Cherie","text":"Yeah, that's what we agreed on."},{"start":119.75,"end":123.11,"speaker":"Julian","text":"Okay, just checking. And who are we presenting to?"},{"start":123.69,"end":128.15,"speaker":"Cherie","text":"Do you never pay attention? We are presenting to all the department heads."},{"start":128.15,"end":134.28,"speaker":"Julian","text":"All the department heads? Wow, no pressure there then. And where are we presenting?"},{"start":134.88,"end":139.42,"speaker":"Cherie","text":"The board room. You know the big room on the top floor with the view and-"},{"start":139.42,"end":143.76,"speaker":"Julian","text":"Yeah, yeah, I know where the board room is. Well, we'd better get going then."},{"start":144.56,"end":148.7,"speaker":"Julian","text":"How much do we need to get ready? I mean, how long does it have to be?"},{"start":149.54,"end":156.14,"speaker":"Cherie","text":"Well, all three of us will be doing a section. So I think if we do five PowerPoint slides each."},{"start":156.72,"end":164.02,"speaker":"Bonnie","text":"Yeah, that's what I was thinking. Five slides each, which is 15 PowerPoint slides in total."},{"start":164.92,"end":168.66,"speaker":"Julian","text":"So just to confirm, what were the three sections again?"},{"start":169.46,"end":173.58,"speaker":"Cherie","text":"You were joking, aren't you? Right. I can see you're not."},{"start":174.5,"end":177.86,"speaker":"Cherie","text":"Right. Well, Bonnie is going to look at the history of World Expos."},{"start":178.74,"end":182.28,"speaker":"Julian","text":"Oh, I thought you were doing the history of World Expos."},{"start":182.84,"end":187.96,"speaker":"Cherie","text":"No, that's Bonnie doing that. You are looking at the good and bad things about World Expos."},{"start":188.26,"end":194.16,"speaker":"Julian","text":"Yeah, yeah, I remember Jasmine did say she wanted us to find the bad things as well as the good."},{"start":194.82,"end":199.72,"speaker":"Julian","text":"So what are you doing, Cherie? I'm looking at the future of World Expos, remember?"},{"start":200.32,"end":204.0,"speaker":"Cherie","text":"We already read a bit on the future of World Expos online on the webpage."},{"start":204.5,"end":211.08,"speaker":"Julian","text":"Oh yeah, okay. I remember. Right. So what I wanted to do today was to draw up a work schedule."},{"start":211.08,"end":214.22,"speaker":"Cherie","text":"You know, so we know who's doing what and when."},{"start":215.46,"end":218.42,"speaker":"Bonnie","text":"Okay, maybe I can take notes and send you it later."},{"start":219.1,"end":224.44,"speaker":"Julian","text":"Oh, I was going to say, I was speaking to a friend of mine, Leo Roy, the other day."},{"start":225.08,"end":229.26,"speaker":"Julian","text":"You know Leo? No, no. Yeah, I know Leo. Remember?"},{"start":229.72,"end":236.24,"speaker":"Julian","text":"Oh yeah, of course. Well, Leo told me his dad worked on the Shanghai Expo in 2010."},{"start":236.8,"end":240.82,"speaker":"Julian","text":"So I've arranged to meet up with him. His dad, I mean. And interview him."},{"start":241.34,"end":243.7,"speaker":"Cherie","text":"Fantastic. So when are you meeting him?"},{"start":244.28,"end":249.82,"speaker":"Julian","text":"Oh, I can't remember. It was either the 8th or 9th of August. Something like that."},{"start":250.72,"end":254.1,"speaker":"Cherie","text":"So which was it? We're trying to do a schedule here."},{"start":254.44,"end":258.47,"speaker":"Julian","text":"Right. Let me check my phone. Right. The Wednesday."},{"start":259.25,"end":265.33,"speaker":"Cherie","text":"Hold on. So you're interviewing Mr. Roy on Wednesday, the 9th of August."},{"start":266.36,"end":269.52,"speaker":"Cherie","text":"Is his surname spelled R-O-Y?"},{"start":270.02,"end":270.8,"speaker":"Julian","text":"Yes, it is."},{"start":271.2,"end":272.68,"speaker":"Cherie","text":"You were pretty sure about that."},{"start":273.4,"end":278.1,"speaker":"Bonnie","text":"Hey, did you read the email from Jasmine? She said that Professor Leung"},{"start":278.1,"end":283.0,"speaker":"Bonnie","text":"at Hong Kong Metropolitan University is giving a talk about World Expos."},{"start":283.72,"end":284.78,"speaker":"Bonnie","text":"One of us should go."},{"start":285.42,"end":287.6,"speaker":"Cherie","text":"Do you know when that is?"},{"start":288.2,"end":291.58,"speaker":"Bonnie","text":"I think she said Saturday morning on 19th August."},{"start":292.28,"end":293.3,"speaker":"Cherie","text":"I can't go to it."},{"start":293.3,"end":297.02,"speaker":"Cherie","text":"Bonnie, why don't you go? You could see if we can include"},{"start":297.02,"end":300.32,"speaker":"Cherie","text":"some of the information in our presentation on the 30th."},{"start":300.76,"end":304.26,"speaker":"Bonnie","text":"Yeah, great. Okay, I'll make a note of that."},{"start":304.74,"end":312.5,"speaker":"Bonnie","text":"A talk on expos at the Metropolitan University on Saturday, the 19th."},{"start":312.84,"end":318.66,"speaker":"Cherie","text":"Great. So I think we should meet up at some point to talk about all the information we've collected."},{"start":319.62,"end":322.92,"speaker":"Bonnie","text":"Good idea. When would be a good time for you?"},{"start":323.36,"end":325.86,"speaker":"Cherie","text":"How about Monday, the 21st?"},{"start":326.38,"end":328.28,"speaker":"Bonnie","text":"No, it's a public holiday, remember?"},{"start":329.26,"end":332.24,"speaker":"Cherie","text":"How about the day after the public holiday then?"},{"start":333.3,"end":335.4,"speaker":"Julian","text":"For what? Sorry, I was miles away."},{"start":336.1,"end":337.56,"speaker":"Cherie","text":"For the progress meeting."},{"start":337.96,"end":338.88,"speaker":"Bonnie","text":"Yeah, fine, yeah."},{"start":339.54,"end":341.26,"speaker":"Cherie","text":"Yeah, me too. Okay."},{"start":342.23,"end":347.85,"speaker":"Cherie","text":"Well, then I'm happy to take all the information and do a first draft of the PowerPoint presentation"},{"start":347.85,"end":348.71,"speaker":"Cherie","text":"if you like."},{"start":349.35,"end":351.19,"speaker":"Bonnie","text":"Fantastic. Thanks, Cherie."},{"start":351.19,"end":356.27,"speaker":"Bonnie","text":"When do you think you can get the first draft of the PowerPoint presentation done by?"},{"start":357.5,"end":360.12,"speaker":"Bonnie","text":"Jasmine said she'd definitely have to see it beforehand."},{"start":361.28,"end":364.26,"speaker":"Cherie","text":"I can give a first draft to Jasmine on the 23rd."},{"start":364.86,"end":367.6,"speaker":"Cherie","text":"It will take me a few hours to put it all together."},{"start":368.04,"end":368.44,"speaker":"Bonnie","text":"Okay?"},{"start":369.0,"end":375.54,"speaker":"Bonnie","text":"Give Jasmine the first draft of the PowerPoint presentation on the 23rd of August."},{"start":376.26,"end":376.5,"speaker":"Cherie","text":"Great."},{"start":377.3,"end":380.54,"speaker":"Bonnie","text":"Could we practice the presentation sometime around about then?"},{"start":381.1,"end":383.74,"speaker":"Cherie","text":"How about doing it on Saturday, 26th?"},{"start":384.58,"end":386.26,"speaker":"Cherie","text":"All of us will need to do it."},{"start":386.76,"end":387.46,"speaker":"Cherie","text":"Would that be okay?"},{"start":388.2,"end":389.6,"speaker":"Bonnie","text":"Yeah, that's fine with me."},{"start":390.2,"end":392.34,"speaker":"Cherie","text":"Fantastic. Is that fine with you, Julian?"},{"start":393.0,"end":394.18,"speaker":"Julian","text":"Sure, no problem."},{"start":394.84,"end":397.16,"speaker":"Cherie","text":"Great. Looks like we are very organised."},{"start":399.51,"end":401.53,"speaker":"Exam Narrator","text":"That is the end of task one."},{"start":402.23,"end":406.13,"speaker":"Exam Narrator","text":"You now have 30 seconds to tidy up your answers."}],"2":[{"start":1.03,"end":1.47,"speaker":"Exam Narrator","text":"Task 2. "},{"start":2.61,"end":5.63,"speaker":"Exam Narrator","text":"You are attending a lecture by Professor Leung."},{"start":5.63,"end":9.77,"speaker":"Exam Narrator","text":"Who is going to talk about the history of World Expos."},{"start":11.15,"end":15.21,"speaker":"Exam Narrator","text":"Listen and fill in the missing information in the space below."},{"start":16.48,"end":19.18,"speaker":"Exam Narrator","text":"One has been provided as an example."},{"start":20.75,"end":24.47,"speaker":"Exam Narrator","text":"You now have 30 seconds to study the task."},{"start":25.42,"end":30.32,"speaker":"Exam Narrator","text":"At the end of the task, you will have one minute to tidy up your answers."},{"start":62.37,"end":63.97,"speaker":"Professor Leung","text":"Good evening, ladies and gentlemen."},{"start":63.97,"end":66.89,"speaker":"Professor Leung","text":"Thank you for joining me here this evening."},{"start":67.33,"end":72.97,"speaker":"Professor Leung","text":"In 2010, Shanghai celebrated the biggest ever world expo."},{"start":73.77,"end":77.69,"speaker":"Professor Leung","text":"Millions of people from all over the world came to Shanghai"},{"start":77.69,"end":82.15,"speaker":"Professor Leung","text":"to see the exhibits and innovations the expo had to offer."},{"start":83.36,"end":89.4,"speaker":"Professor Leung","text":"It is this coming together of people that makes World Expos so special to me."},{"start":90.09,"end":95.95,"speaker":"Professor Leung","text":"And that's why the topic of my lecture tonight is a history of World Expos,"},{"start":96.53,"end":97.77,"speaker":"Professor Leung","text":"bringing people together."},{"start":98.56,"end":102.84,"speaker":"Professor Leung","text":"Because expos do just that. They bring people together."},{"start":104.1,"end":109.08,"speaker":"Professor Leung","text":"So first, I thought I'd tell you a little bit about what expos are,"},{"start":109.28,"end":112.52,"speaker":"Professor Leung","text":"and then we'll explore the history of World Expos,"},{"start":112.6,"end":116.14,"speaker":"Professor Leung","text":"which I shall break into three stages to show you"},{"start":116.14,"end":119.62,"speaker":"Professor Leung","text":"how they developed into the World Expos we know today."},{"start":121.0,"end":127.29,"speaker":"Professor Leung","text":"So, to begin at the beginning, what exactly are World Expos?"},{"start":128.21,"end":133.3,"speaker":"Professor Leung","text":"Well, World Expos are, quite simply, international exhibitions."},{"start":134.14,"end":135.84,"speaker":"Professor Leung","text":"One country is the host."},{"start":136.74,"end":141.24,"speaker":"Professor Leung","text":"Basically, the host country has two major things to do."},{"start":141.82,"end":145.64,"speaker":"Professor Leung","text":"First, it has to decide on a theme for the exhibition."},{"start":146.58,"end":151.22,"speaker":"Professor Leung","text":"The theme is very important for the expo, as it gives it its focus."},{"start":151.9,"end":155.22,"speaker":"Professor Leung","text":"Secondly, having decided on a theme,"},{"start":156.06,"end":159.84,"speaker":"Professor Leung","text":"the host has to invite other countries to join the exhibition."},{"start":161.6,"end":166.26,"speaker":"Professor Leung","text":"So, now we know what World Expos are and why we have them,"},{"start":166.66,"end":169.2,"speaker":"Professor Leung","text":"let's move on to the history of World Expos."},{"start":170.17,"end":174.47,"speaker":"Professor Leung","text":"Basically, World Expos developed in three main stages."},{"start":176.21,"end":182.59,"speaker":"Professor Leung","text":"The first phase, or stage, is focused on industrial and technological inventions."},{"start":183.4,"end":191.02,"speaker":"Professor Leung","text":"This phase began way back in 1851 and really lasted until about 1938."},{"start":192.33,"end":199.41,"speaker":"Professor Leung","text":"So, the very first world expo was held in 1851 in the wonderful city of London, England."},{"start":200.67,"end":202.95,"speaker":"Professor Leung","text":"It was called the Great Exhibition,"},{"start":203.71,"end":210.89,"speaker":"Professor Leung","text":"and the idea was to promote all the very latest inventions for improving industry and farming."},{"start":212.35,"end":219.6,"speaker":"Professor Leung","text":"Ten countries, including China, were invited to join in and display their latest technology."},{"start":221.37,"end":225.17,"speaker":"Professor Leung","text":"6.3 million visitors came to see the Great Exhibition."},{"start":225.97,"end":228.29,"speaker":"Professor Leung","text":"It was a truly amazing event."},{"start":229.28,"end":234.72,"speaker":"Professor Leung","text":"The Great Exhibition had several major achievements, but I'd like to highlight two."},{"start":236.07,"end":241.55,"speaker":"Professor Leung","text":"The first is what people thought was the major achievement of the Great Exhibition at the time,"},{"start":241.55,"end":246.03,"speaker":"Professor Leung","text":"which was they grew the biggest flower in the world."},{"start":246.99,"end":252.35,"speaker":"Professor Leung","text":"And this flower, the biggest flower, was so big a child could stand on its leaf."},{"start":253.05,"end":254.43,"speaker":"Professor Leung","text":"So, we're talking big."},{"start":255.72,"end":261.14,"speaker":"Professor Leung","text":"The second major achievement was raising awareness of farming techniques."},{"start":261.88,"end":264.98,"speaker":"Professor Leung","text":"The increase of awareness of different farming techniques"},{"start":264.98,"end":269.28,"speaker":"Professor Leung","text":"learned from the Great Expo brought huge benefits to the world."},{"start":270.56,"end":276.6,"speaker":"Professor Leung","text":"The second stage in the development of World Expos focused on cultural exchange."},{"start":277.78,"end":283.86,"speaker":"Professor Leung","text":"This stage is called cultural exchange because from about 1939 to 1987,"},{"start":284.7,"end":289.08,"speaker":"Professor Leung","text":"World Expos focused more on themes that were important culturally."},{"start":290.54,"end":297.86,"speaker":"Professor Leung","text":"One of the first World Expos of this kind took place in New York, America, in 1939."},{"start":298.99,"end":303.68,"speaker":"Professor Leung","text":"As I've said before, all World Expos have a particular theme,"},{"start":304.42,"end":308.36,"speaker":"Professor Leung","text":"and the theme of this world expo was the City of Tomorrow."},{"start":309.89,"end":316.31,"speaker":"Professor Leung","text":"To show the City of Tomorrow, the New York Expo had huge exhibitions on modern food"},{"start":316.31,"end":320.23,"speaker":"Professor Leung","text":"and displayed the latest works of art from different countries."},{"start":321.02,"end":326.0,"speaker":"Professor Leung","text":"So, it combined different aspects of culture, food, and art."},{"start":327.02,"end":330.08,"speaker":"Professor Leung","text":"Again, this was a very popular world expo."},{"start":330.86,"end":335.64,"speaker":"Professor Leung","text":"50 countries took part and over 44 million people went to it."},{"start":337.53,"end":344.17,"speaker":"Professor Leung","text":"Finally, the third stage in the development of World Expos was really all about nation branding."},{"start":345.14,"end":351.76,"speaker":"Professor Leung","text":"The nation branding stage started around 1988 and is still going on now, really."},{"start":352.7,"end":357.49,"speaker":"Professor Leung","text":"This meant that the host country and all participating countries"},{"start":357.49,"end":360.11,"speaker":"Professor Leung","text":"used the expo to promote themselves."},{"start":361.39,"end":367.53,"speaker":"Professor Leung","text":"An example of an expo in the nation branding stage took place in Hanover in Germany."},{"start":368.52,"end":372.7,"speaker":"Professor Leung","text":"The theme for this expo was nature and technology."},{"start":373.72,"end":378.78,"speaker":"Professor Leung","text":"The idea was to promote environmentally friendly products and inventions"},{"start":379.21,"end":381.94,"speaker":"Professor Leung","text":"and to look at ways of saving the environment."},{"start":384.02,"end":386.08,"speaker":"Professor Leung","text":"155 countries were invited."},{"start":386.88,"end":392.22,"speaker":"Professor Leung","text":"But unfortunately, the number of visitors was lower than what had been expected."},{"start":392.98,"end":399.28,"speaker":"Professor Leung","text":"Only about 25 million people came to the expo, so it was considered to be a bit of a failure."},{"start":401.91,"end":404.21,"speaker":"Exam Narrator","text":"That is the end of task two."},{"start":405.05,"end":408.37,"speaker":"Exam Narrator","text":"You now have one minute to tidy up your answers."}],"3":[{"start":1.04,"end":8.15,"speaker":"Exam Narrator","text":"Task 3. , Cherie has just shown Bonnie and Julian a draft of her PowerPoint slides"},{"start":8.15,"end":9.49,"speaker":"Exam Narrator","text":"for the presentation."},{"start":11.0,"end":14.24,"speaker":"Exam Narrator","text":"Bonnie and Julian are now giving her some feedback."},{"start":15.26,"end":19.48,"speaker":"Exam Narrator","text":"Listen to the conversation and make notes in the note sheet below."},{"start":20.7,"end":23.04,"speaker":"Exam Narrator","text":"One has been provided as an example."},{"start":24.07,"end":27.61,"speaker":"Exam Narrator","text":"You now have 30 seconds to study the task."},{"start":28.72,"end":33.6,"speaker":"Exam Narrator","text":"At the end of the task, you will have one minute to tidy up your answers."},{"start":65.47,"end":67.13,"speaker":"Cherie","text":"Okay, so what do you think?"},{"start":67.99,"end":70.45,"speaker":"Bonnie","text":"Well, I think it's brilliant overall."},{"start":70.97,"end":72.67,"speaker":"Bonnie","text":"You've done a really good job."},{"start":73.64,"end":76.24,"speaker":"Cherie","text":"But I'm sensing a but here."},{"start":76.94,"end":82.08,"speaker":"Cherie","text":"But, well, I think it might be a bit light on content."},{"start":83.48,"end":86.2,"speaker":"Cherie","text":"Okay, so I was thinking that as well."},{"start":86.9,"end":88.74,"speaker":"Cherie","text":"We could maybe add a couple more slides."},{"start":88.74,"end":92.4,"speaker":"Cherie","text":"What do you think is missing or it could be expanded on?"},{"start":93.4,"end":97.06,"speaker":"Julian","text":"Yeah, I was wondering if we needed more on the downsides."},{"start":97.38,"end":100.8,"speaker":"Julian","text":"You know, negatives about organizing World Expos."},{"start":101.48,"end":103.62,"speaker":"Julian","text":"So I would add a slide on that."},{"start":104.26,"end":106.98,"speaker":"Julian","text":"Maybe include some key points on the slide."},{"start":107.64,"end":112.54,"speaker":"Julian","text":"The first one would be something about the millions of dollars wasted on World Expos"},{"start":112.54,"end":115.28,"speaker":"Julian","text":"and the fact that the money could be better spent."},{"start":116.08,"end":118.12,"speaker":"Julian","text":"Yeah, I'd include something like that."},{"start":118.84,"end":123.84,"speaker":"Julian","text":"I mean, the host country has to be prepared to spend millions on creating a world expo."},{"start":124.82,"end":129.24,"speaker":"Julian","text":"One of the other downsides we could include is the disruption to life in the host city."},{"start":130.27,"end":132.23,"speaker":"Julian","text":"You know, World Expos have to be built"},{"start":132.23,"end":135.41,"speaker":"Julian","text":"and existing roads to the expo site have to be improved"},{"start":135.41,"end":137.49,"speaker":"Julian","text":"or new roads have to be constructed."},{"start":138.19,"end":142.17,"speaker":"Julian","text":"So it can cause a lot of disruption for people living in the host city."},{"start":143.42,"end":145.24,"speaker":"Julian","text":"Another disadvantage we could include"},{"start":145.24,"end":149.42,"speaker":"Julian","text":"is that very often people complain that the expo buildings are not used again"},{"start":149.42,"end":150.86,"speaker":"Julian","text":"after the end of the expo."},{"start":151.18,"end":151.3,"speaker":"Julian","text":"Really?"},{"start":151.98,"end":155.32,"speaker":"Julian","text":"Yeah, occasionally the buildings are reused."},{"start":156.0,"end":158.26,"speaker":"Julian","text":"But more often than not, they are just taken down."},{"start":158.48,"end":159.96,"speaker":"Julian","text":"So no, they're not reused."},{"start":160.56,"end":163.72,"speaker":"Cherie","text":"Okay, well, I think I can do a slide on that."},{"start":164.4,"end":165.84,"speaker":"Cherie","text":"Is there anything else to include?"},{"start":166.36,"end":167.2,"speaker":"Cherie","text":"Another slide maybe?"},{"start":168.3,"end":174.26,"speaker":"Julian","text":"Well, I think we could include one on the reasons why a city would want to host a world expo."},{"start":174.74,"end":177.3,"speaker":"Julian","text":"I don't think that comes across in our slides."},{"start":178.3,"end":180.0,"speaker":"Cherie","text":"So what would you include then, Bonnie?"},{"start":180.48,"end":181.32,"speaker":"Cherie","text":"What kind of reasons?"},{"start":182.3,"end":183.72,"speaker":"Bonnie","text":"Well, there are lots of reasons."},{"start":184.4,"end":187.0,"speaker":"Bonnie","text":"The first reason for holding a world expo"},{"start":187.0,"end":190.32,"speaker":"Bonnie","text":"would be to promote friendship among different countries."},{"start":191.38,"end":194.68,"speaker":"Bonnie","text":"Many different countries work together on each expo."},{"start":194.88,"end":198.42,"speaker":"Bonnie","text":"So it's a wonderful way to promote international friendship."},{"start":199.22,"end":201.88,"speaker":"Bonnie","text":"The second reason for holding World Expos"},{"start":201.88,"end":205.92,"speaker":"Bonnie","text":"is so that different countries that take part in World Expos"},{"start":205.92,"end":208.52,"speaker":"Bonnie","text":"can build up their national image."},{"start":209.2,"end":212.92,"speaker":"Bonnie","text":"You know, countries can show how beautiful their countries are"},{"start":212.92,"end":214.92,"speaker":"Bonnie","text":"and how friendly their people are."},{"start":215.72,"end":219.3,"speaker":"Bonnie","text":"Plus, holding expos can attract business and tourism."},{"start":220.02,"end":221.86,"speaker":"Cherie","text":"Right, okay, got it."},{"start":222.34,"end":225.08,"speaker":"Cherie","text":"I'll include all these points in two extra slides."},{"start":225.74,"end":228.04,"speaker":"Cherie","text":"I'll get the draft ready to give to Jasmine."},{"start":228.74,"end":229.46,"speaker":"Cherie","text":"Thanks, guys."},{"start":230.1,"end":231.72,"speaker":"Cherie","text":"Any comments on the presentation?"},{"start":232.74,"end":234.18,"speaker":"Cherie","text":"I mean, the way it looks and..."},{"start":234.98,"end":238.16,"speaker":"Julian","text":"Well, I think generally it's a bit wordy."},{"start":238.54,"end":241.06,"speaker":"Julian","text":"You know, too many words on each slide."},{"start":241.78,"end":244.46,"speaker":"Julian","text":"So could we take out some of the writing?"},{"start":245.36,"end":247.0,"speaker":"Cherie","text":"Okay, less writing."},{"start":247.46,"end":248.6,"speaker":"Cherie","text":"Right, hang on."},{"start":249.06,"end":252.24,"speaker":"Cherie","text":"Let me get my laptop to write these comments down so I don't forget."},{"start":253.25,"end":256.17,"speaker":"Julian","text":"Okay, that would help definitely."},{"start":256.77,"end":260.11,"speaker":"Bonnie","text":"Plus, I was thinking we could put in more visuals."},{"start":260.73,"end":261.71,"speaker":"Bonnie","text":"You know, more pictures."},{"start":262.55,"end":265.81,"speaker":"Bonnie","text":"I think it will make the presentation look much more interesting."},{"start":266.73,"end":267.47,"speaker":"Bonnie","text":"What do you think?"},{"start":267.85,"end":269.87,"speaker":"Cherie","text":"Sure, I can add more visuals."},{"start":271.38,"end":273.12,"speaker":"Julian","text":"Yeah, another point I thought of"},{"start":273.12,"end":275.8,"speaker":"Julian","text":"was to change the background color to light blue."},{"start":276.92,"end":278.06,"speaker":"Julian","text":"White looks a bit boring."},{"start":278.62,"end":281.66,"speaker":"Julian","text":"So why not have a light blue background instead of white?"},{"start":281.94,"end":282.94,"speaker":"Julian","text":"So it looks more colorful."},{"start":283.64,"end":286.66,"speaker":"Bonnie","text":"Yeah, I had a similar comment I'd noted down."},{"start":287.62,"end":288.7,"speaker":"Bonnie","text":"What do you think, Cherie?"},{"start":289.16,"end":290.06,"speaker":"Cherie","text":"Yep, fine."},{"start":290.76,"end":293.44,"speaker":"Cherie","text":"I was actually going to do that anyway in the next draft."},{"start":294.0,"end":297.84,"speaker":"Cherie","text":"Okay, so change the background color to light blue."},{"start":298.36,"end":298.68,"speaker":"Cherie","text":"What else?"},{"start":299.54,"end":302.98,"speaker":"Julian","text":"Another point is maybe put all the main headings in red"},{"start":303.5,"end":305.72,"speaker":"Julian","text":"instead of having all the writing in black,"},{"start":306.18,"end":307.48,"speaker":"Julian","text":"just to make it look more interesting."},{"start":308.16,"end":309.28,"speaker":"Cherie","text":"Yeah, good idea."},{"start":309.92,"end":312.46,"speaker":"Cherie","text":"So, put headings in red."},{"start":313.16,"end":315.48,"speaker":"Bonnie","text":"Another point is the size of the writing."},{"start":316.18,"end":317.22,"speaker":"Bonnie","text":"I think it's a bit small."},{"start":317.98,"end":320.78,"speaker":"Bonnie","text":"Can we make it bigger so it's easier for the audience to read?"},{"start":322.52,"end":324.32,"speaker":"Cherie","text":"So make the writing bigger."},{"start":324.94,"end":326.46,"speaker":"Julian","text":"How about changing the font, too?"},{"start":327.2,"end":330.42,"speaker":"Julian","text":"I always think Times New Roman looks so old-fashioned."},{"start":331.38,"end":334.04,"speaker":"Julian","text":"Can we make it more, you know, up-to-date looking?"},{"start":334.58,"end":338.02,"speaker":"Cherie","text":"Okay, change the font to make it look more modern."},{"start":338.88,"end":340.78,"speaker":"Cherie","text":"Actually, in relation to that,"},{"start":340.78,"end":344.56,"speaker":"Cherie","text":"I was wondering whether we should use numbers or bullet points."},{"start":345.02,"end":346.42,"speaker":"Cherie","text":"In the end, I used numbers."},{"start":347.0,"end":349.06,"speaker":"Cherie","text":"But do you think bullet points would look better?"},{"start":349.99,"end":350.73,"speaker":"Julian","text":"Yeah, I do."},{"start":351.37,"end":353.05,"speaker":"Julian","text":"Less formal and more visual."},{"start":353.83,"end":357.13,"speaker":"Cherie","text":"Okay, so change numbers to bullet points."},{"start":357.89,"end":359.31,"speaker":"Cherie","text":"Right, okay, got it."},{"start":359.79,"end":362.25,"speaker":"Cherie","text":"I'll get the drafts ready to give to Jasmine then."},{"start":362.63,"end":363.19,"speaker":"Cherie","text":"Thanks, guys."},{"start":365.59,"end":367.85,"speaker":"Exam Narrator","text":"That's the end of task three."},{"start":368.49,"end":371.79,"speaker":"Exam Narrator","text":"You now have one minute to tidy up your answers."}],"4":[{"start":1.06,"end":2.5,"speaker":"Exam Narrator","text":"Task four."},{"start":4.15,"end":8.55,"speaker":"Exam Narrator","text":"Julian, Bonnie and Cherie have met up with their friend Leo at a café."},{"start":9.74,"end":13.92,"speaker":"Exam Narrator","text":"They are talking about the group's presentation and World Expos."},{"start":15.01,"end":18.81,"speaker":"Exam Narrator","text":"Listen to the conversation and answer the questions below."},{"start":19.87,"end":24.41,"speaker":"Exam Narrator","text":"Please note that you do not need to answer in complete sentences."},{"start":25.35,"end":27.97,"speaker":"Exam Narrator","text":"One has been provided as an example."},{"start":29.16,"end":32.86,"speaker":"Exam Narrator","text":"You now have 30 seconds to study the task."},{"start":33.95,"end":38.69,"speaker":"Exam Narrator","text":"At the end of the task, you will have three minutes to tidy up your answers."},{"start":70.29,"end":71.51,"speaker":"Leo","text":"Okay, right."},{"start":72.05,"end":73.15,"speaker":"Leo","text":"I've got my cappuccino."},{"start":73.99,"end":75.15,"speaker":"Leo","text":"Anybody else want anything?"},{"start":75.83,"end":76.39,"speaker":"Bonnie","text":"No, thanks."},{"start":76.87,"end":77.33,"speaker":"Cherie","text":"No, no."},{"start":78.05,"end":78.77,"speaker":"Julian","text":"No, thanks, Leo."},{"start":79.31,"end":80.09,"speaker":"Leo","text":"How are you doing anyway?"},{"start":80.71,"end":81.25,"speaker":"Julian","text":"I'm okay."},{"start":81.61,"end":81.81,"speaker":"Leo","text":"Good."},{"start":82.73,"end":82.89,"speaker":"Leo","text":"Right."},{"start":83.47,"end":87.45,"speaker":"Leo","text":"Well, I remembered you said to look out for some stuff about expos."},{"start":87.45,"end":91.41,"speaker":"Leo","text":"So, I asked my dad, and he sent me a link on YouTube."},{"start":92.11,"end":94.05,"speaker":"Leo","text":"I thought it might be quite interesting for you."},{"start":94.65,"end":100.09,"speaker":"Leo","text":"You did say you were looking into the negative aspects of World Expos and trade fairs."},{"start":100.23,"end":104.07,"speaker":"Leo","text":"So this, you might call that the dark side of the history."},{"start":104.31,"end":104.65,"speaker":"Cherie","text":"Really?"},{"start":104.99,"end":105.41,"speaker":"Leo","text":"Yeah."},{"start":106.15,"end":112.37,"speaker":"Leo","text":"The clip was basically about the experiences of this one African man called Ota Benga."},{"start":113.19,"end":117.83,"speaker":"Leo","text":"The clip started off giving a pretty interesting insight into these world exhibitions."},{"start":118.9,"end":125.06,"speaker":"Leo","text":"They said the main function of these expos for ordinary people wasn't trade or science,"},{"start":125.24,"end":130.46,"speaker":"Leo","text":"but rather it was the only way that normal people could see things from around the world."},{"start":131.24,"end":133.98,"speaker":"Leo","text":"Very few people could travel abroad in those days, of course."},{"start":134.44,"end":135.92,"speaker":"Bonnie","text":"Yeah, I'd never thought of that."},{"start":136.32,"end":138.32,"speaker":"Leo","text":"Yeah, so that was one thing."},{"start":138.88,"end":145.28,"speaker":"Leo","text":"But there was also this other more sinister, darker side of the expos and fairs,"},{"start":145.44,"end":151.4,"speaker":"Leo","text":"where they exhibited humans from different parts of the world, like in a human zoo."},{"start":152.53,"end":157.07,"speaker":"Leo","text":"They reckon that more than 35,000 men, women, and children"},{"start":157.07,"end":163.27,"speaker":"Leo","text":"were exhibited in these types of human zoos at various expos in Paris, London,"},{"start":163.27,"end":169.58,"speaker":"Leo","text":"you know, the USA, at the end of the 19th and into the 20th century."},{"start":170.52,"end":170.82,"speaker":"Cherie","text":"Really?"},{"start":171.92,"end":175.4,"speaker":"Bonnie","text":"What did they make these people do in these human zoos?"},{"start":176.7,"end":182.46,"speaker":"Leo","text":"Well, once there, they had to like live, they lived in traditional houses."},{"start":183.24,"end":185.7,"speaker":"Leo","text":"These traditional houses were built especially there."},{"start":186.38,"end":189.74,"speaker":"Leo","text":"And these people, they did the cooking and so on."},{"start":189.74,"end":193.7,"speaker":"Leo","text":"And people watched them like they watch monkeys at a zoo."},{"start":194.62,"end":199.36,"speaker":"Leo","text":"And at certain times of the day, they put on some sort of exotic show,"},{"start":199.96,"end":203.68,"speaker":"Leo","text":"doing some dances or religious rituals, that sort of thing."},{"start":204.62,"end":208.88,"speaker":"Julian","text":"Wow, so it was really like the dolphin show at Ocean Park then?"},{"start":209.16,"end":210.42,"speaker":"Leo","text":"Yeah, pretty much."},{"start":211.15,"end":215.19,"speaker":"Leo","text":"The most famous of these people who was in one of these human zoos"},{"start":215.19,"end":218.07,"speaker":"Leo","text":"was an African man named Ota Benga."},{"start":218.07,"end":219.71,"speaker":"Leo","text":"He was a pygmy."},{"start":220.37,"end":220.63,"speaker":"Bonnie","text":"A what?"},{"start":221.89,"end":222.43,"speaker":"Leo","text":"A pygmy."},{"start":222.97,"end":227.03,"speaker":"Leo","text":"You know, a tribe from western Africa who were smaller than average humans."},{"start":227.61,"end":228.63,"speaker":"Bonnie","text":"Oh, yeah, right."},{"start":229.09,"end":230.11,"speaker":"Leo","text":"And that was the point."},{"start":230.75,"end":231.95,"speaker":"Leo","text":"That's why he was there."},{"start":233.06,"end":234.98,"speaker":"Cherie","text":"What? Because he was a pygmy."},{"start":235.38,"end":235.68,"speaker":"Leo","text":"Yeah."},{"start":236.3,"end":241.48,"speaker":"Leo","text":"You see, for the 1904 Great World Fair in St. Louis in the USA,"},{"start":242.3,"end":245.84,"speaker":"Leo","text":"there was this American scientist called W.J. McGee."},{"start":246.64,"end":250.78,"speaker":"Leo","text":"Now, McGee wanted to put on a spectacular exhibition of humankind."},{"start":251.91,"end":256.65,"speaker":"Leo","text":"He wanted to exhibit the most extreme examples of man from around the world."},{"start":257.13,"end":260.33,"speaker":"Leo","text":"The tallest, the smallest, that sort of thing."},{"start":261.01,"end":265.45,"speaker":"Leo","text":"So he got the smallest people from Africa, and that was Ota Benga."},{"start":266.2,"end":269.9,"speaker":"Leo","text":"He was from the tribe of pygmies, the smallest people in the world."},{"start":270.69,"end":275.31,"speaker":"Leo","text":"So McGee sent this explorer on a huge expedition to Africa"},{"start":275.31,"end":277.67,"speaker":"Leo","text":"to find pygmies and bring them back."},{"start":278.68,"end":279.2,"speaker":"Leo","text":"So he did."},{"start":279.94,"end":283.48,"speaker":"Leo","text":"He brought back Ota Benga and five other pygmies."},{"start":284.22,"end":284.46,"speaker":"Julian","text":"Wow."},{"start":285.4,"end":286.36,"speaker":"Cherie","text":"That's amazing."},{"start":287.22,"end":288.2,"speaker":"Leo","text":"Yeah, I know."},{"start":289.06,"end":292.84,"speaker":"Leo","text":"The irony was that Ota Benga and his fellow tribes people"},{"start":292.84,"end":296.66,"speaker":"Leo","text":"thought that they were in the USA to show off their own culture."},{"start":297.22,"end":302.42,"speaker":"Leo","text":"Whereas, in fact, what they were advertised to the public and scientists as"},{"start":303.02,"end":305.5,"speaker":"Leo","text":"was the most primitive people on the planet."},{"start":306.36,"end":307.12,"speaker":"Bonnie","text":"That's terrible."},{"start":308.2,"end":309.78,"speaker":"Bonnie","text":"And what happened after the fair ended?"},{"start":310.59,"end":314.43,"speaker":"Leo","text":"Well, after the end of the fair, Ota went to New York."},{"start":315.23,"end":317.93,"speaker":"Leo","text":"You imagine this little African guy in New York,"},{"start":318.65,"end":321.77,"speaker":"Leo","text":"you know, with all its skyscrapers and high-tech lifestyle."},{"start":322.85,"end":324.87,"speaker":"Julian","text":"So what did he do in New York?"},{"start":325.43,"end":326.93,"speaker":"Julian","text":"Did he work or..."},{"start":326.93,"end":328.31,"speaker":"Leo","text":"Well, sort of."},{"start":328.95,"end":332.45,"speaker":"Leo","text":"He then became famous because he got a job at a zoo in New York."},{"start":333.3,"end":335.74,"speaker":"Leo","text":"He thought he was going to look after the elephants,"},{"start":336.64,"end":341.76,"speaker":"Leo","text":"but he was actually given a job to be a live exhibit in the zoo."},{"start":342.68,"end":345.04,"speaker":"Leo","text":"He shared a cage with a chimpanzee."},{"start":345.62,"end":346.58,"speaker":"Cherie","text":"That's awful."},{"start":347.38,"end":349.5,"speaker":"Leo","text":"Well, to be fair to people in New York,"},{"start":349.82,"end":353.16,"speaker":"Leo","text":"they did protest and write to the newspapers complaining about it."},{"start":353.62,"end":354.8,"speaker":"Bonnie","text":"So what happened?"},{"start":355.48,"end":357.92,"speaker":"Leo","text":"The exhibition was stopped after about a week."},{"start":359.54,"end":361.06,"speaker":"Bonnie","text":"So then what happened to him?"},{"start":361.82,"end":364.58,"speaker":"Leo","text":"Well, it just got worse and worse for Ota."},{"start":365.3,"end":367.02,"speaker":"Leo","text":"He then tried to settle in America"},{"start":367.02,"end":371.58,"speaker":"Leo","text":"and even ended up working in a tobacco factory in a small town in the US."},{"start":372.9,"end":376.28,"speaker":"Leo","text":"But he was so homesick that he wanted to return to Africa,"},{"start":376.72,"end":379.22,"speaker":"Leo","text":"but he didn't have enough money to pay for the journey."},{"start":379.99,"end":382.85,"speaker":"Leo","text":"So in the end, he never returned to Africa."},{"start":384.15,"end":385.35,"speaker":"Cherie","text":"That's terrible."},{"start":386.29,"end":388.11,"speaker":"Julian","text":"No wonder it's not very well known."},{"start":389.24,"end":392.24,"speaker":"Cherie","text":"That is a truly horrendous story, Leo."},{"start":393.04,"end":395.82,"speaker":"Leo","text":"God, how can you treat somebody like that?"},{"start":396.4,"end":398.84,"speaker":"Leo","text":"So, are you going to include it in the presentation?"},{"start":399.78,"end":400.76,"speaker":"Leo","text":"What do you think, Bonnie?"},{"start":401.74,"end":403.24,"speaker":"Bonnie","text":"I think we should."},{"start":403.94,"end":405.5,"speaker":"Bonnie","text":"Jasmine wanted the full picture,"},{"start":405.86,"end":410.22,"speaker":"Bonnie","text":"so this gives them the full picture of the history of these types of expos."},{"start":410.8,"end":411.54,"speaker":"Bonnie","text":"That's for sure."},{"start":412.18,"end":413.48,"speaker":"Leo","text":"Mm. Cherie?"},{"start":414.95,"end":416.45,"speaker":"Cherie","text":"Well, I'm not so keen."},{"start":417.29,"end":420.41,"speaker":"Cherie","text":"I mean, you have to remember that a couple of the audience"},{"start":420.41,"end":424.19,"speaker":"Cherie","text":"when we present are actually American, from the USA."},{"start":425.23,"end":429.01,"speaker":"Cherie","text":"I mean, we don't want to offend anybody with our presentation, do we?"},{"start":429.63,"end":430.57,"speaker":"Leo","text":"What do you think, Julian?"},{"start":431.39,"end":432.81,"speaker":"Julian","text":"Well, I think we should."},{"start":433.65,"end":437.61,"speaker":"Julian","text":"But only the first half of his story is directly relevant to expos."},{"start":438.41,"end":441.69,"speaker":"Julian","text":"His experiences in New York and the zoo are less relevant."},{"start":442.05,"end":445.01,"speaker":"Julian","text":"So just including the first half would keep it relevant."},{"start":447.49,"end":451.69,"speaker":"Exam Narrator","text":"That is the end of task four and of Part A."},{"start":452.33,"end":457.11,"speaker":"Exam Narrator","text":"You now have three minutes to complete your answers to task four"},{"start":457.11,"end":460.57,"speaker":"Exam Narrator","text":"and to tidy up all your other answers."}]},"partB":[{"start":1.63,"end":5.86,"speaker":"Exam Narrator","text":"Part B, look at page two of your data file."},{"start":7.28,"end":7.7,"speaker":"Exam Narrator","text":"Situation."},{"start":8.88,"end":10.48,"speaker":"Exam Narrator","text":"You are Nico Lynn."},{"start":11.32,"end":13.54,"speaker":"Exam Narrator","text":"You work for Events Horizon,"},{"start":14.18,"end":17.7,"speaker":"Exam Narrator","text":"a company which organises large public events."},{"start":18.83,"end":23.93,"speaker":"Exam Narrator","text":"You are part of a committee responsible for organising the Victoria Cup,"},{"start":24.41,"end":26.87,"speaker":"Exam Narrator","text":"a professional women's tennis tournament."},{"start":28.47,"end":31.65,"speaker":"Exam Narrator","text":"In order to promote the Victoria Cup to the public,"},{"start":32.39,"end":36.05,"speaker":"Exam Narrator","text":"the head of the Victoria Cup project team, Anthony Au,"},{"start":36.43,"end":39.91,"speaker":"Exam Narrator","text":"is keen to ensure that the tournament is a success."},{"start":40.96,"end":45.24,"speaker":"Exam Narrator","text":"You will listen to a Zoom meeting between a young tennis star"},{"start":45.24,"end":51.2,"speaker":"Exam Narrator","text":"called Lara Terranova, her agent Victor Laurent and Anthony Au."},{"start":52.63,"end":56.45,"speaker":"Exam Narrator","text":"Before the recording is played, you will have five minutes"},{"start":56.45,"end":60.35,"speaker":"Exam Narrator","text":"to study the question answer book and the data file"},{"start":60.35,"end":64.51,"speaker":"Exam Narrator","text":"to familiarise yourself with the situation and the tasks."},{"start":65.47,"end":68.49,"speaker":"Exam Narrator","text":"Complete the tasks by following the instructions"},{"start":68.49,"end":72.07,"speaker":"Exam Narrator","text":"in the question answer book and on the recording."},{"start":73.08,"end":77.58,"speaker":"Exam Narrator","text":"You will find all the information you need in the question answer book,"},{"start":77.98,"end":80.28,"speaker":"Exam Narrator","text":"the data file and on the recording."},{"start":81.2,"end":86.08,"speaker":"Exam Narrator","text":"As you listen, you can make notes on page three of the data file."},{"start":87.05,"end":90.69,"speaker":"Exam Narrator","text":"You now have five minutes to familiarise yourself"},{"start":90.69,"end":93.97,"speaker":"Exam Narrator","text":"with the question answer book and the data file."},{"start":396.26,"end":397.42,"speaker":"Exam Narrator","text":"Recording is about to begin."},{"start":397.42,"end":401.32,"speaker":"Exam Narrator","text":"Turn to page three of the data file."},{"start":407.0,"end":408.06,"speaker":"Anthony Au","text":"Hi, Victor and Lara."},{"start":408.74,"end":410.26,"speaker":"Anthony Au","text":"This is Anthony from Events Horizon."},{"start":410.86,"end":411.48,"speaker":"Anthony Au","text":"Can you hear me?"},{"start":412.32,"end":414.38,"speaker":"Victor Laurent","text":"Hi, Anthony. Yes, we can hear you."},{"start":414.9,"end":417.08,"speaker":"Lara Terranova","text":"Hi, Anthony. How are things in Hong Kong?"},{"start":417.66,"end":419.68,"speaker":"Anthony Au","text":"Yeah, pretty good. Yep, great."},{"start":420.4,"end":423.74,"speaker":"Anthony Au","text":"Okay. Well, we've got a few things to run through about,"},{"start":423.74,"end":426.86,"speaker":"Anthony Au","text":"you know, you coming to Hong Kong for the Victoria Cup."},{"start":427.28,"end":427.54,"speaker":"Anthony Au","text":"Yeah."},{"start":428.87,"end":431.63,"speaker":"Anthony Au","text":"We could maybe start with any concerns you've got"},{"start":431.63,"end":435.41,"speaker":"Anthony Au","text":"about coming to Hong Kong at all or the tournament or..."},{"start":435.41,"end":436.71,"speaker":"Victor Laurent","text":"Yes. Well..."},{"start":437.41,"end":438.95,"speaker":"Lara Terranova","text":"Maybe I can start."},{"start":439.59,"end":440.75,"speaker":"Victor Laurent","text":"Yes, go ahead, Lara. Sorry."},{"start":441.43,"end":445.71,"speaker":"Lara Terranova","text":"Yeah. My main worry, Anthony, is the weather really."},{"start":446.35,"end":449.23,"speaker":"Lara Terranova","text":"You know, it's so hot and humid in Hong Kong."},{"start":449.87,"end":453.23,"speaker":"Lara Terranova","text":"I mean, I really don't want to get ill from being too hot."},{"start":453.73,"end":455.47,"speaker":"Lara Terranova","text":"I know last year was quite bad."},{"start":456.83,"end":460.31,"speaker":"Anthony Au","text":"Yeah. We've been discussing this issue quite extensively"},{"start":460.31,"end":463.51,"speaker":"Anthony Au","text":"after last year, and it was decided by the committee"},{"start":463.51,"end":467.11,"speaker":"Anthony Au","text":"to allow the players to take longer breaks between games."},{"start":467.55,"end":471.17,"speaker":"Lara Terranova","text":"Longer breaks? Hmm. That sounds like a sensible idea."},{"start":471.87,"end":472.99,"speaker":"Lara Terranova","text":"How long will they be then?"},{"start":473.71,"end":477.07,"speaker":"Anthony Au","text":"Well, players will be allowed eight minutes between games."},{"start":477.57,"end":479.01,"speaker":"Lara Terranova","text":"Eight minutes. That's good."},{"start":479.59,"end":481.23,"speaker":"Victor Laurent","text":"And what about the playing schedule?"},{"start":481.59,"end":482.99,"speaker":"Victor Laurent","text":"Could Lara play in the evening?"},{"start":483.41,"end":486.57,"speaker":"Anthony Au","text":"Absolutely. Actually, another major change this year"},{"start":486.57,"end":489.43,"speaker":"Anthony Au","text":"is that all of our matches will be played in the evenings."},{"start":489.43,"end":492.19,"speaker":"Anthony Au","text":"So players can avoid the heat of the afternoon."},{"start":492.73,"end":494.91,"speaker":"Lara Terranova","text":"Oh, really? That's much better."},{"start":495.43,"end":497.61,"speaker":"Lara Terranova","text":"I always prefer evening games anyway."},{"start":498.41,"end":502.11,"speaker":"Anthony Au","text":"Okay. Sounds good. Victor, you want to say something?"},{"start":502.67,"end":505.69,"speaker":"Victor Laurent","text":"Yes. Another concern is the air quality."},{"start":505.89,"end":506.77,"speaker":"Lara Terranova","text":"Oh, yeah."},{"start":507.43,"end":510.33,"speaker":"Anthony Au","text":"Okay. Air quality. You mean the pollution?"},{"start":510.77,"end":514.21,"speaker":"Victor Laurent","text":"Yes. Again, from our past experience in the Far East,"},{"start":514.49,"end":517.11,"speaker":"Victor Laurent","text":"the pollution levels are often really high,"},{"start":517.11,"end":520.63,"speaker":"Victor Laurent","text":"and this makes it difficult for players to breathe a lot of the time."},{"start":521.17,"end":522.45,"speaker":"Anthony Au","text":"Yeah. Point taken, Victor."},{"start":523.55,"end":525.59,"speaker":"Anthony Au","text":"Again, it's something the committee has been talking about."},{"start":526.19,"end":528.09,"speaker":"Anthony Au","text":"I mean, we've talked about pollution with the government"},{"start":528.09,"end":532.01,"speaker":"Anthony Au","text":"and the other players, and what has been decided is as follows."},{"start":532.89,"end":536.63,"speaker":"Anthony Au","text":"If the API level is above 200 during the event,"},{"start":537.21,"end":538.89,"speaker":"Anthony Au","text":"we can use an indoor court."},{"start":539.82,"end":543.0,"speaker":"Victor Laurent","text":"So you've booked an indoor court in case it is too polluted?"},{"start":543.44,"end":544.28,"speaker":"Anthony Au","text":"Yeah, that's right."},{"start":544.28,"end":548.5,"speaker":"Anthony Au","text":"But we'll only use it if the API level is above 200."},{"start":549.58,"end":552.24,"speaker":"Victor Laurent","text":"Excellent. I think all players will appreciate you"},{"start":552.24,"end":555.82,"speaker":"Victor Laurent","text":"going that extra mile to avoid putting players' health in danger."},{"start":556.6,"end":558.44,"speaker":"Lara Terranova","text":"Yes. I agree 100%."},{"start":559.48,"end":562.3,"speaker":"Lara Terranova","text":"Oh, yes. I remember what I was going to say."},{"start":563.12,"end":568.34,"speaker":"Lara Terranova","text":"One of my other concerns is, how shall I put this?"},{"start":569.0,"end":570.72,"speaker":"Lara Terranova","text":"The behavior of the fans."},{"start":571.54,"end":573.96,"speaker":"Lara Terranova","text":"I remember the last time I was in Hong Kong,"},{"start":573.96,"end":577.62,"speaker":"Lara Terranova","text":"the fans were talking really loudly during the game."},{"start":578.38,"end":579.64,"speaker":"Lara Terranova","text":"It's very distracting."},{"start":580.44,"end":581.24,"speaker":"Lara Terranova","text":"You know what I mean?"},{"start":581.7,"end":584.74,"speaker":"Lara Terranova","text":"I know it isn't a majority, but you know..."},{"start":584.74,"end":586.24,"speaker":"Anthony Au","text":"No, no, we get it."},{"start":586.78,"end":589.74,"speaker":"Anthony Au","text":"We just received a letter from a fan on this very topic."},{"start":590.48,"end":594.3,"speaker":"Anthony Au","text":"So, it was decided that if any fan breaks the rules"},{"start":594.3,"end":596.52,"speaker":"Anthony Au","text":"concerning making noise during play,"},{"start":597.04,"end":598.82,"speaker":"Anthony Au","text":"they will be removed from the venue."},{"start":599.16,"end":599.64,"speaker":"Lara Terranova","text":"Oh, really?"},{"start":600.22,"end":601.42,"speaker":"Lara Terranova","text":"So they'll be removed?"},{"start":602.06,"end":605.32,"speaker":"Lara Terranova","text":"Okay. I'll be interested to see how that goes."},{"start":605.96,"end":608.48,"speaker":"Anthony Au","text":"And something else that will hopefully help this year is"},{"start":608.48,"end":611.24,"speaker":"Anthony Au","text":"we've introduced a system whereby the members"},{"start":611.24,"end":614.48,"speaker":"Anthony Au","text":"of the local tennis clubs get priority in booking tickets."},{"start":615.1,"end":617.5,"speaker":"Anthony Au","text":"This will mean that real fans will get tickets."},{"start":618.14,"end":620.82,"speaker":"Lara Terranova","text":"Good. A bit of support for local tennis."},{"start":621.68,"end":623.52,"speaker":"Anthony Au","text":"Oh, I wanted to ask you, Lara."},{"start":623.92,"end":624.3,"speaker":"Lara Terranova","text":"Yeah?"},{"start":624.8,"end":626.66,"speaker":"Anthony Au","text":"Would you be willing to spend some time meeting"},{"start":626.66,"end":629.42,"speaker":"Anthony Au","text":"and teaching some of your young Hong Kong fans?"},{"start":629.42,"end":632.44,"speaker":"Anthony Au","text":"We're organizing a tennis activity day."},{"start":633.1,"end":635.6,"speaker":"Lara Terranova","text":"Yeah, I'd love to. It sounds fun."},{"start":636.38,"end":637.76,"speaker":"Lara Terranova","text":"You can send us the details."},{"start":638.46,"end":639.86,"speaker":"Lara Terranova","text":"Um, how old are the participants?"},{"start":640.66,"end":642.04,"speaker":"Anthony Au","text":"Well, they're different families,"},{"start":642.46,"end":645.54,"speaker":"Anthony Au","text":"but we have an age requirement for the child or children."},{"start":646.18,"end":648.28,"speaker":"Anthony Au","text":"They have to be between 12 and 16."},{"start":649.1,"end":650.56,"speaker":"Lara Terranova","text":"12 to 16 years old."},{"start":650.86,"end":651.6,"speaker":"Victor Laurent","text":"So, teenagers."},{"start":652.44,"end":653.98,"speaker":"Anthony Au","text":"And we have to select them."},{"start":654.5,"end":657.06,"speaker":"Anthony Au","text":"I mean, there are a lot of teenagers who want to take part,"},{"start":657.32,"end":659.06,"speaker":"Anthony Au","text":"so we have to select them."},{"start":659.42,"end":661.28,"speaker":"Anthony Au","text":"Maybe you could help with that."},{"start":661.6,"end":662.3,"speaker":"Lara Terranova","text":"Sure, no problem."},{"start":662.92,"end":664.12,"speaker":"Lara Terranova","text":"I'd be happy to do that."},{"start":664.66,"end":666.18,"speaker":"Lara Terranova","text":"Just let me know the details later."},{"start":667.46,"end":667.66,"speaker":"Anthony Au","text":"Okay."},{"start":668.32,"end":669.94,"speaker":"Anthony Au","text":"The other thing I wanted to talk to you about"},{"start":669.94,"end":672.4,"speaker":"Anthony Au","text":"was the donations to the two Hong Kong charities."},{"start":673.16,"end":676.34,"speaker":"Anthony Au","text":"The Refugee Sanctuary and the Change Young Lives."},{"start":676.94,"end":677.4,"speaker":"Victor Laurent","text":"Oh, yes."},{"start":677.76,"end":681.08,"speaker":"Victor Laurent","text":"Well, I've looked at the details of the charities you sent me,"},{"start":681.32,"end":684.84,"speaker":"Victor Laurent","text":"and we'd like to go ahead with making the donation to both of them."},{"start":685.34,"end":686.94,"speaker":"Anthony Au","text":"Oh, that's great news. Great."},{"start":686.94,"end":690.26,"speaker":"Victor Laurent","text":"Can we discuss the details again just now?"},{"start":691.22,"end":694.44,"speaker":"Victor Laurent","text":"Okay, well, what we would want to do"},{"start":694.44,"end":698.68,"speaker":"Victor Laurent","text":"is something similar to what Suzy Gilmore did with you last year in Hong Kong."},{"start":698.86,"end":699.4,"speaker":"Victor Laurent","text":"Oh, yeah?"},{"start":700.16,"end":703.5,"speaker":"Victor Laurent","text":"We propose to donate, let's see, in Hong Kong dollars."},{"start":703.98,"end":707.28,"speaker":"Victor Laurent","text":"It would be half a million Hong Kong dollars to each charity."},{"start":707.76,"end":710.2,"speaker":"Victor Laurent","text":"But it's on the condition that they use the money"},{"start":710.2,"end":712.72,"speaker":"Victor Laurent","text":"to convert one of their rooms into a gym."},{"start":712.72,"end":718.22,"speaker":"Anthony Au","text":"Okay, so 500,000 Hong Kong dollars towards setting up a gym."},{"start":718.72,"end":719.06,"speaker":"Anthony Au","text":"And?"},{"start":719.18,"end":723.62,"speaker":"Victor Laurent","text":"And in return, the gym is to be called the Lara Terranova Gym."},{"start":724.28,"end":726.24,"speaker":"Anthony Au","text":"Right. The Lara Terranova Gym."},{"start":726.58,"end":728.64,"speaker":"Anthony Au","text":"Right. That should be okay."},{"start":729.5,"end":732.44,"speaker":"Victor Laurent","text":"Oh, and can we set up a short courtesy visit"},{"start":732.44,"end":734.4,"speaker":"Victor Laurent","text":"to their charity centres during the tournament?"},{"start":735.1,"end":737.56,"speaker":"Victor Laurent","text":"You know, so you could go to the charity centres?"},{"start":737.78,"end":738.56,"speaker":"Lara Terranova","text":"Yeah, definitely."},{"start":739.32,"end":740.78,"speaker":"Anthony Au","text":"Please go ahead and organise that."},{"start":741.14,"end":742.26,"speaker":"Anthony Au","text":"That would be very nice."},{"start":742.26,"end":744.82,"speaker":"Anthony Au","text":"Great. Is there anything else?"},{"start":745.5,"end":746.9,"speaker":"Victor Laurent","text":"No, I think that's everything."},{"start":747.38,"end":748.92,"speaker":"Victor Laurent","text":"Oh, the advert?"},{"start":749.6,"end":752.74,"speaker":"Victor Laurent","text":"Oh, yes. Lara was a little..."},{"start":752.74,"end":755.4,"speaker":"Lara Terranova","text":"Yeah, maybe I can tell him myself, thanks."},{"start":756.44,"end":760.2,"speaker":"Lara Terranova","text":"Yeah, I was a bit surprised to see your advertisements for the tournament."},{"start":760.92,"end":765.84,"speaker":"Lara Terranova","text":"I was told by my sponsor that my image would appear on the advert for the event,"},{"start":766.18,"end":769.16,"speaker":"Lara Terranova","text":"since I am the highest ranking player taking part."},{"start":769.79,"end":773.92,"speaker":"Lara Terranova","text":"And that the highest ranking player should therefore be on the poster."},{"start":774.72,"end":777.4,"speaker":"Lara Terranova","text":"And that certainly isn't Suzy Gilmore."},{"start":777.96,"end":780.94,"speaker":"Anthony Au","text":"Oh, yeah. Sorry about that."},{"start":782.1,"end":785.54,"speaker":"Anthony Au","text":"Yes, we've been having all sorts of problems with that poster,"},{"start":785.92,"end":789.32,"speaker":"Anthony Au","text":"so I'll pass on your message to the PR department."},{"start":789.84,"end":790.88,"speaker":"Lara Terranova","text":"Okay, thank you."},{"start":791.42,"end":792.4,"speaker":"Victor Laurent","text":"Okay, thanks, Anthony."},{"start":793.0,"end":797.22,"speaker":"Victor Laurent","text":"Can I have your phone number in case we have any other questions later on?"},{"start":797.22,"end":801.04,"speaker":"Anthony Au","text":"Yes, we have a new number for all player inquiries."},{"start":803.52,"end":809.52,"speaker":"Anthony Au","text":"It's 00852 1747 3562."},{"start":810.28,"end":811.64,"speaker":"Victor Laurent","text":"Let me repeat it back to you."},{"start":813.84,"end":816.74,"speaker":"Victor Laurent","text":"00852 1747 3562."},{"start":817.12,"end":817.48,"speaker":"Anthony Au","text":"That's it."},{"start":818.36,"end":820.86,"speaker":"Anthony Au","text":"Otherwise, feel free to send me an email any time."},{"start":821.38,"end":821.96,"speaker":"Victor Laurent","text":"Great, thanks."},{"start":822.34,"end":822.8,"speaker":"Anthony Au","text":"No problem."},{"start":823.42,"end":824.3,"speaker":"Anthony Au","text":"Bye for now."},{"start":826.63,"end":830.29,"speaker":"Exam Narrator","text":"That is the end of the listening component of this paper."},{"start":831.38,"end":836.34,"speaker":"Exam Narrator","text":"You will now have one hour and 15 minutes to complete the written tasks"},{"start":836.34,"end":841.0,"speaker":"Exam Narrator","text":"in either part B1 or part B2."},{"start":841.86,"end":844.58,"speaker":"Exam Narrator","text":"An announcement will be made when time is up."},{"start":845.64,"end":849.0,"speaker":"Exam Narrator","text":"Take off your earphones now and turn off the radio."}]});})();
